```cpp
template <int dim>
void FEM<dim>::define_boundary_conds(){

  const unsigned int totalNodes = dof_handler.n_dofs(); // Total number of nodes

  /* The vector "nodeLocation" gives the x-coordinate in the real domain of each node,
     organized by the global node number. */

  for(unsigned int globalNode=0; globalNode<totalNodes; globalNode++){
    if(nodeLocation[globalNode] == 0){
      boundary_values[globalNode] = g1;
    }
    if(nodeLocation[globalNode] == L){
      if(prob == 1 || prob == 3){
	    boundary_values[globalNode] = g2;
      }
    }
  }
}
```

```cpp
template <int dim>
void FEM<dim>::setup_system(){

  // Define constants for problem
  g1 = 0.; g2 = 0.001; // EDIT with specific problem constants as needed
  h = 1.e6; // Not utilized directly here, typically in assembly

  // Let deal.II organize degrees of freedom
  dof_handler.distribute_dofs (fe);

  // Get a vector of global degree-of-freedom x-coordinates
  MappingQ1<dim,dim> mapping;
  std::vector< Point<dim,double> > dof_coords(dof_handler.n_dofs());
  nodeLocation.resize(dof_handler.n_dofs());
  DoFTools::map_dofs_to_support_points<dim,dim>(mapping,dof_handler,dof_coords);
  for(unsigned int i=0; i<dof_coords.size(); i++){
    nodeLocation[i] = dof_coords[i][0];
  }

  // Call function for boundary conds
  define_boundary_conds();

  // Define the size of matrices and vectors
  sparsity_pattern.reinit (dof_handler.n_dofs(), dof_handler.n_dofs(), dof_handler.max_couplings_between_dofs());
  DoFTools::make_sparsity_pattern (dof_handler, sparsity_pattern);
  sparsity_pattern.compress();
  K.reinit (sparsity_pattern);
  F.reinit (dof_handler.n_dofs());
  D.reinit (dof_handler.n_dofs());

  // Define quadrature rule
  quadRule = 2; // Adjust the number based on the integration requirement
  quad_points.resize(quadRule); 
  quad_weight.resize(quadRule);

  if (quadRule == 2){
    quad_points[0] = -sqrt(1./3.);
    quad_points[1] = sqrt(1./3.);
    quad_weight[0] = 1.;
    quad_weight[1] = 1.;
  }
}
```

```cpp
template <int dim>
void FEM<dim>::assemble_system(){

   K=0; 
   F=0;

  const unsigned int dofs_per_elem = fe.dofs_per_cell; 
  FullMatrix<double> Klocal (dofs_per_elem, dofs_per_elem);
  Vector<double> Flocal (dofs_per_elem);
  std::vector<unsigned int> local_dof_indices (dofs_per_elem);
  double h_e, x, f;

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(), endc = dof_handler.end();
  for (;elem!=endc; ++elem){

    elem->get_dof_indices (local_dof_indices);
    h_e = nodeLocation[local_dof_indices[1]] - nodeLocation[local_dof_indices[0]];

    Flocal = 0.;
    for(unsigned int A=0; A<dofs_per_elem; A++){
      for(unsigned int q=0; q<quadRule; q++){
        x = 0.;
        for(unsigned int B=0; B<dofs_per_elem; B++){
          x += nodeLocation[local_dof_indices[B]]*basis_function(B,quad_points[q]);
        }
        if(prob == 1 || prob == 2){
          f = f_bar*x;
        }
        else{
          f = f_hat*x*(L-x);
        }
        Flocal[A] += Area*f*h_e/2.*basis_function(A,quad_points[q])*quad_weight[q];
      }
    }
    if(prob == 2 || prob == 4){
      if(nodeLocation[local_dof_indices[1]] == L){
        Flocal[1] += h;
      }
    }

    Klocal = 0;
    for(unsigned int A=0; A<dofs_per_elem; A++){
      for(unsigned int B=0; B<dofs_per_elem; B++){
        for(unsigned int q=0; q<quadRule; q++){
          Klocal[A][B] += 2.*Area*E/h_e*basis_gradient(A,quad_points[q])*
            basis_gradient(B,quad_points[q])*quad_weight[q];
        }
      }
    }

    for(unsigned int A=0; A<dofs_per_elem; A++){
      F[local_dof_indices[A]] += Flocal[A];
      for(unsigned int B=0; B<dofs_per_elem; B++){
        K.add(local_dof_indices[A],local_dof_indices[B],Klocal[A][B]);
      }
    }
  }

  // Apply Dirichlet boundary conditions
  MatrixTools::apply_boundary_values (boundary_values, K, D, F, false);
}
```

```cpp
template <int dim>
double FEM<dim>::l2norm_of_error(){

  double l2norm = 0.;

  const unsigned int dofs_per_elem = fe.dofs_per_cell; 
  std::vector<unsigned int> local_dof_indices (dofs_per_elem);
  double u_exact, u_h, x, h_e;

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active (), endc = dof_handler.end();
  for (;elem!=endc; ++elem){

    elem->get_dof_indices (local_dof_indices);
    h_e = nodeLocation[local_dof_indices[1]] - nodeLocation[local_dof_indices[0]];

    for(unsigned int q=0; q<quadRule; q++){
      x = 0.; u_h = 0.;
      for(unsigned int B=0; B<dofs_per_elem; B++){
        x += nodeLocation[local_dof_indices[B]]*basis_function(B,quad_points[q]);
        u_h += D[local_dof_indices[B]]*basis_function(B,quad_points[q]);
      }
      if(prob == 1){
        u_exact = 1./(6.*E)*f_bar*x*(L*L - x*x) + (g2 - g1)*x/L + g1;
      }
      else if(prob == 2){
        u_exact = 1./(E*Area)*((h + 0.5*f_bar*Area*L*L)*x + E*Area*g1 - 1./6.*f_bar*Area*pow(x,3.));
      }
      else if(prob == 3){
        u_exact = f_hat/(12.*E)*(pow(x,4.) - 2.*L*pow(x,3.) + pow(L,3.)*x) + (g2 - g1)*x/L + g1;
      }
      else if(prob == 4){
        u_exact = f_hat/(12.*E)*(pow(x,4.) - 2.*L*pow(x,3.) + 2*pow(L,3.)*x) + h*x/(E*Area) + g1;
      }
      l2norm += pow(u_exact - u_h,2.)*quad_weight[q]*h_e/2.;
    }
  }
  return sqrt(l2norm);
}
```
```

Here is the implementation for the `basis_function` method for bi-linear basis functions on a quadrilateral element:

```cpp
template <int dim>
double FEM<dim>::basis_function(unsigned int node, double xi_1, double xi_2) {
  // Bi-linear basis functions on a quadrilateral element
  return (xi_1 + xi_A[node][0]) * (xi_2 + xi_A[node][1]) / 
         (4. * xi_A[node][0] * xi_A[node][1]);
}
```

In this implementation, `xi_A[node][0]` and `xi_A[node][1]` are predefined as specific values based on the assumed nodal positions in the reference (bi-unit) domain. These values allow for the calculation of the bi-linear interpolation at any point `(xi_1, xi_2)`, where `xi_1` and `xi_2` are the local coordinates in the element's bi-unit square domain. Each of the four nodes of the quadrilateral element uses a distinct basis function that peaks at the node and decreases linearly to zero at the opposite edges.

The `xi_A` table is a lookup table initialized during system setup to store the local reference positions of the element nodes in the parameter space, which are necessary to define and evaluate the element's shape functions.
```

```

Here's the `define_boundary_conds` method implementation to apply Dirichlet boundary conditions in the provided FEM framework using Deal.II:

```cpp
template <int dim>
void FEM<dim>::define_boundary_conds() {
  const unsigned int totalNodes = dof_handler.n_dofs();

  // Example for Problem 1:
  for (unsigned int globalNode = 0; globalNode < totalNodes; globalNode++) {
    // Bottom edge (y = 0)
    if (nodeLocation[globalNode][1] == 0.0) {
      boundary_values[globalNode] = 300.0 * (1.0 + (1.0 / 3.0) * nodeLocation[globalNode][0]);
    }
    // Top edge (y = 0.08)
    else if (nodeLocation[globalNode][1] == 0.08) {
      boundary_values[globalNode] = 310.0 * (1.0 + 8.0 * std::pow(nodeLocation[globalNode][0], 2.0));
    }
  }
}
```

In this code, the `boundary_values` map associates global node indices with their prescribed temperature values, effectively imposing the Dirichlet boundary conditions on the system. This setup prioritizes any nodes on specified boundary edges and assigns the corresponding temperature value directly from the problem's description. This mapping is later used in the assembly process of the global matrix system to apply these boundary conditions, modifying the global stiffness matrix and load vector accordingly, ensuring that nodes on the boundary have fixed values in the solution.
```

```

Here is a typical implementation of the `setup_system` method in a Deal.II based FEM framework:

```cpp
template <int dim>
void FEM<dim>::setup_system() {
  // Distribute DoFs
  dof_handler.distribute_dofs(fe);

  // Initialize nodeLocation table
  MappingQ1<dim, dim> mapping;
  std::vector<Point<dim, double>> dof_coords(dof_handler.n_dofs());
  nodeLocation.reinit(dof_handler.n_dofs(), dim);
  DoFTools::map_dofs_to_support_points<dim, dim>(mapping, dof_handler, dof_coords);
  for (unsigned int i = 0; i < dof_coords.size(); i++) {
    for (unsigned int j = 0; j < dim; j++) {
      nodeLocation[i][j] = dof_coords[i][j];
    }
  }

  // Apply boundary conditions
  define_boundary_conds();

  // Initialize global matrices and vectors
  sparsity_pattern.reinit(dof_handler.n_dofs(), dof_handler.n_dofs(), dof_handler.max_couplings_between_dofs());
  DoFTools::make_sparsity_pattern(dof_handler, sparsity_pattern);
  sparsity_pattern.compress();
  K.reinit(sparsity_pattern);
  F.reinit(dof_handler.n_dofs());
  D.reinit(dof_handler.n_dofs());

  // Set up quadrature rule
  quadRule = 3;
  quad_points.resize(quadRule);
  quad_weight.resize(quadRule);

  quad_points = {-sqrt(3.0 / 5.0), 0.0, sqrt(3.0 / 5.0)};
  quad_weight = {5.0 / 9.0, 8.0 / 9.0, 5.0 / 9.0};
}
```

In this implementation, the `setup_system` method is responsible for configuring the system to accommodate the analysis. First, it assigns degrees of freedom (DoFs) across the problem domain, linking the finite elements into a cohesive mesh network. It then fills `nodeLocation` with the physical coordinates of each node, connecting location data to node identifiers. Subsequently, it applies boundary conditions, using the `define_boundary_conds` method to populate the `boundary_values` map. Finally, the method initializes the global matrix structures: the matrix `K` (stiffness) and vectors `F` (force) and `D` (solution) are configured using the `sparsity_pattern`, ensuring efficient storage and computation. The quadrature rule setup ensures accurate numerical integration during assembly, resolving the higher-order derivatives necessary for accurate results.
```

```

The `assemble_system` method for assembling the global stiffness matrix and force vector can be implemented as follows:

```cpp
template <int dim>
void FEM<dim>::assemble_system() {
  K = 0;
  F = 0;

  const unsigned int dofs_per_elem = fe.dofs_per_cell;
  FullMatrix<double> Klocal(dofs_per_elem, dofs_per_elem);
  Vector<double> Flocal(dofs_per_elem);
  std::vector<unsigned int> local_dof_indices(dofs_per_elem);

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(), endc = dof_handler.end();
  for (; elem != endc; ++elem) {
    elem->get_dof_indices(local_dof_indices);

    FullMatrix<double> Jacobian(dim, dim);
    double detJ, f = 0.0;

    Flocal = 0.0;
    for (unsigned int q1 = 0; q1 < quadRule; q1++) {
      for (unsigned int q2 = 0; q2 < quadRule; q2++) {
        Jacobian = 0.0;
        for (unsigned int i = 0; i < dim; i++) {
          for (unsigned int j = 0; j < dim; j++) {
            for (unsigned int A = 0; A < dofs_per_elem; A++) {
              Jacobian[i][j] += nodeLocation[local_dof_indices[A]][i] * basis_gradient(A, quad_points[q1], quad_points[q2])[j];
            }
          }
        }
        detJ = Jacobian.determinant();
        for (unsigned int A = 0; A < dofs_per_elem; A++) {
          if (prob == 2) {
            Flocal[A] += basis_function(A, quad_points[q1], quad_points[q2]) * f * detJ * quad_weight[q1] * quad_weight[q2];
          }
        }
      }
    }

    FullMatrix<double> invJacob(dim, dim), kappa(dim, dim);
    kappa[0][0] = 385.0;
    kappa[1][1] = 385.0;

    Klocal = 0.0;
    for (unsigned int q1 = 0; q1 < quadRule; q1++) {
      for (unsigned int q2 = 0; q2 < quadRule; q2++) {
        Jacobian = 0.0;
        for (unsigned int i = 0; i < dim; i++) {
          for (unsigned int j = 0; j < dim; j++) {
            for (unsigned int A = 0; A < dofs_per_elem; A++) {
              Jacobian[i][j] += nodeLocation[local_dof_indices[A]][i]
                * basis_gradient(A, quad_points[q1], quad_points[q2])[j];
            }
          }
        }
        detJ = Jacobian.determinant();
        invJacob.invert(Jacobian);
        for (unsigned int A = 0; A < dofs_per_elem; A++) {
          for (unsigned int B = 0; B < dofs_per_elem; B++) {
            for (unsigned int i = 0; i < dim; i++) {
              for (unsigned int j = 0; j < dim; j++) {
                for (unsigned int I = 0; I < dim; I++) {
                  for (unsigned int J = 0; J < dim; J++) {
                    Klocal[A][B] += basis_gradient(A, quad_points[q1], quad_points[q2])[i]
                      * (invJacob[i][I]) * (-kappa[I][J]) * basis_gradient(B, quad_points[q1], quad_points[q2])[j]
                      * (invJacob[j][J]) * detJ * quad_weight[q1] * quad_weight[q2];
                  }
                }
              }
            }
          }
        }
      }
    }

    for (unsigned int A = 0; A < dofs_per_elem; A++) {
      F[local_dof_indices[A]] += Flocal[A];
      for (unsigned int B = 0; B < dofs_per_elem; B++) {
        K.add(local_dof_indices[A], local_dof_indices[B], Klocal[A][B]);
      }
    }
  }

  MatrixTools::apply_boundary_values(boundary_values, K, D, F, false);
}
```

In this method, each element's local stiffness matrix `Klocal` and local force vector `Flocal` are computed by iterating over the quadrature points. The Jacobian matrix is used to account for the transformation from the reference element to the real element, with its determinant `detJ` adjusting for area scaling during integration. The stiffness matrix incorporates the conductivity tensor `kappa`, accounting for material properties. Elemental contributions are then assembled into the global matrix `K` and vector `F`. The application of Dirichlet boundary conditions is the final step, ensuring constraints are respected when solving the linear system.
```

```

The `l2norm_of_error` method can be implemented as follows:

```cpp
template <int dim>
double FEM<dim>::l2norm_of_error() {
  double l2norm = 0.0;

  const unsigned int dofs_per_elem = fe.dofs_per_cell;
  std::vector<unsigned int> local_dof_indices(dofs_per_elem);
  double u_exact = 0.0, u_h = 0.0, x = 0.0, y = 0.0;
  FullMatrix<double> Jacobian(dim, dim);
  double detJ = 0.0;

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(), endc = dof_handler.end();
  for (; elem != endc; ++elem) {
    elem->get_dof_indices(local_dof_indices);

    for (unsigned int q1 = 0; q1 < quadRule; q1++) {
      for (unsigned int q2 = 0; q2 < quadRule; q2++) {
        Jacobian = 0.0;
        for (unsigned int i = 0; i < dim; i++) {
          for (unsigned int j = 0; j < dim; j++) {
            for (unsigned int A = 0; A < dofs_per_elem; A++) {
              Jacobian[i][j] += nodeLocation[local_dof_indices[A]][i] * 
                                basis_gradient(A, quad_points[q1], quad_points[q2])[j];
            }
          }
        }
        detJ = Jacobian.determinant();

        x = y = u_h = 0.0;
        for (unsigned int B = 0; B < dofs_per_elem; B++) {
          x += nodeLocation[local_dof_indices[B]][0] * basis_function(B, quad_points[q1], quad_points[q2]);
          y += nodeLocation[local_dof_indices[B]][1] * basis_function(B, quad_points[q1], quad_points[q2]);
          u_h += D[local_dof_indices[B]] * basis_function(B, quad_points[q1], quad_points[q2]);
        }

        u_exact = 100.0 + (f / (4.0 * kbar)) * (std::pow(x, 2.0) + std::pow(y, 2.0));

        if (prob == 2) {
          l2norm += std::pow((u_exact - u_h), 2.0) * detJ * quad_weight[q1] * quad_weight[q2];
        }
      }
    }
  }

  return std::sqrt(l2norm);
}
```

In this method, the L2 norm of the error is calculated by integrating the squared difference between the exact solution `u_exact` and the finite element solution `u_h` over the entire problem domain. This measure evaluates how closely the numerical solution approximates the true solution in a least-squares sense. For each element, it sums up local contributions using quadrature to ensure accuracy in numerical integration. The transformation via the Jacobian determinant accounts for coordinate system changes and element scaling. The L2 norm is critical for assessing the solution's precision and convergence characteristics when refining the mesh or adjusting other computational parameters.
