    double x_min = 0.0, x_max = 0.03, y_min = 0.0, y_max = 0.08;

    Point<dim,double> min(x_min, y_min), max(x_max, y_max);
    GridGenerator::subdivided_hyper_rectangle(triangulation, numberOfElements, min, max);
