```cpp
template <int dim>
double FEM<dim>::basis_function(unsigned int node, double xi_1, double xi_2) {
    // Basis function values at the node within quadrilateral elements
    return (xi_1 + xi_A[node][0]) * (xi_2 + xi_A[node][1]) / (4.0 * xi_A[node][0] * xi_A[node][1]);
}

template <int dim>
std::vector<double> FEM<dim>::basis_gradient(unsigned int node, double xi_1, double xi_2) {
    std::vector<double> values(dim, 0.0); // Gradient vector
    values[0] = (xi_2 + xi_A[node][1]) / (4.0 * xi_A[node][0] * xi_A[node][1]);
    values[1] = (xi_1 + xi_A[node][0]) / (4.0 * xi_A[node][0] * xi_A[node][1]);
    return values;
}
```

```cpp
template <int dim>
void FEM<dim>::assemble_system() {
    K = 0;
    F = 0;

    const unsigned int dofs_per_elem = fe.dofs_per_cell;
    FullMatrix<double> Klocal(dofs_per_elem, dofs_per_elem);
    Vector<double> Flocal(dofs_per_elem);
    std::vector<unsigned int> local_dof_indices(dofs_per_elem);

    typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(), endc = dof_handler.end();
    for (; elem != endc; ++elem) {
        elem->get_dof_indices(local_dof_indices);

        FullMatrix<double> Jacobian(dim, dim);
        FullMatrix<double> invJacob(dim, dim), kappa(dim, dim);
        kappa[0][0] = 385.0;
        kappa[1][1] = 385.0;
        double detJ;

        Klocal = 0;
        for (unsigned int q1 = 0; q1 < quadRule; ++q1) {
            for (unsigned int q2 = 0; q2 < quadRule; ++q2) {
                Jacobian = 0;
                for (unsigned int i = 0; i < dim; ++i) {
                    for (unsigned int j = 0; j < dim; ++j) {
                        for (unsigned int A = 0; A < dofs_per_elem; ++A) {
                            Jacobian[i][j] += nodeLocation[local_dof_indices[A]][i] * basis_gradient(A, quad_points[q1], quad_points[q2])[j];
                        }
                    }
                }
                detJ = Jacobian.determinant();
                invJacob.invert(Jacobian);

                for (unsigned int A = 0; A < dofs_per_elem; ++A) {
                    for (unsigned int B = 0; B < dofs_per_elem; ++B) {
                        for (unsigned int i = 0; i < dim; ++i) {
                            for (unsigned int j = 0; j < dim; ++j) {
                                for (unsigned int I = 0; I < dim; ++I) {
                                    for (unsigned int J = 0; J < dim; ++J) {
                                        Klocal[A][B] += -basis_gradient(A, quad_points[q1], quad_points[q2])[I] * invJacob[I][i] * kappa[i][j]
                                            * basis_gradient(B, quad_points[q1], quad_points[q2])[J] * invJacob[J][j] * detJ
                                            * quad_weight[q1] * quad_weight[q2];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        for (unsigned int A = 0; A < dofs_per_elem; ++A) {
            F[local_dof_indices[A]] += Flocal[A];
            for (unsigned int B = 0; B < dofs_per_elem; ++B) {
                K.add(local_dof_indices[A], local_dof_indices[B], Klocal[A][B]);
            }
        }
    }
    MatrixTools::apply_boundary_values(boundary_values, K, D, F, false);
}
```

```cpp
template <int dim>
void FEM<dim>::solve() {
    // Solve for D
    SparseDirectUMFPACK A;
    A.initialize(K);
    A.vmult(D, F); // D=K^{-1}*F
}
```
```

```cpp
template <int dim>
double FEM<dim>::basis_function(unsigned int node, double xi_1, double xi_2, double xi_3) {
    double value = 0.; // Store the value of the basis function in this variable

    if(node == 0){
        value = (1. - xi_1)*(1. - xi_2)*(1. - xi_3) / 8.;
    } else if(node == 1){
        value = (1. + xi_1)*(1. - xi_2)*(1. - xi_3) / 8.;
    } else if(node == 2){
        value = (1. - xi_1)*(1. + xi_2)*(1. - xi_3) / 8.;
    } else if(node == 3){
        value = (1. + xi_1)*(1. + xi_2)*(1. - xi_3) / 8.;
    } else if(node == 4){
        value = (1. - xi_1)*(1. - xi_2)*(1. + xi_3) / 8.;
    } else if(node == 5){
        value = (1. + xi_1)*(1. - xi_2)*(1. + xi_3) / 8.;
    } else if(node == 6){
        value = (1. - xi_1)*(1. + xi_2)*(1. + xi_3) / 8.;
    } else if(node == 7){
        value = (1. + xi_1)*(1. + xi_2)*(1. + xi_3) / 8.;
    } else {
        std::cout << "Error: invalid node number.\n";
        exit(1);
    }

    return value;
}
```

```cpp
template <int dim>
std::vector<double> FEM<dim>::basis_gradient(unsigned int node, double xi_1, double xi_2, double xi_3) {
    std::vector<double> values(dim, 0.0); // Store the gradient of the basis function in this variable

    if(node == 0){
        values[0] = -(1 - xi_2)*(1 - xi_3) / 8.;
        values[1] = -(1. - xi_1)*(1 - xi_3) / 8.;
        values[2] = -(1. - xi_1)*(1 - xi_2) / 8.;
    } else if(node == 1){
        values[0] = (1 - xi_2)*(1 - xi_3) / 8.;
        values[1] = -(1. + xi_1)*(1 - xi_3) / 8.;
        values[2] = -(1. + xi_1)*(1 - xi_2) / 8.;
    } else if(node == 2){
        values[0] = -(1 + xi_2)*(1 - xi_3) / 8.;
        values[1] = (1. - xi_1)*(1 - xi_3) / 8.;
        values[2] = -(1. - xi_1)*(1 + xi_2) / 8.;
    } else if(node == 3){
        values[0] = (1 + xi_2)*(1 - xi_3) / 8.;
        values[1] = (1. + xi_1)*(1 - xi_3) / 8.;
        values[2] = -(1. + xi_1)*(1 + xi_2) / 8.;
    } else if(node == 4){
        values[0] = -(1 - xi_2)*(1 + xi_3) / 8.;
        values[1] = -(1. - xi_1)*(1 + xi_3) / 8.;
        values[2] = (1. - xi_1)*(1 - xi_2) / 8.;
    } else if(node == 5){
        values[0] = (1 - xi_2)*(1 + xi_3) / 8.;
        values[1] = -(1. + xi_1)*(1 + xi_3) / 8.;
        values[2] = (1. + xi_1)*(1 - xi_2) / 8.;
    } else if(node == 6){
        values[0] = -(1 + xi_2)*(1 + xi_3) / 8.;
        values[1] = (1. - xi_1)*(1 + xi_3) / 8.;
        values[2] = (1. - xi_1)*(1 + xi_2) / 8.;
    } else if(node == 7){
        values[0] = (1 + xi_2)*(1 + xi_3) / 8.;
        values[1] = (1. + xi_1)*(1 + xi_3) / 8.;
        values[2] = (1. + xi_1)*(1 + xi_2) / 8.;
    } else {
        std::cout << "Error: invalid node number.\n";
        exit(1);
    }

    return values;
}
