```cpp
template <int dim>
void FEM<dim>::apply_initial_conditions() {
    const unsigned int totalDOFs = dof_handler.n_dofs(); // Total number of nodes
    double x;
    unsigned int nodal_dof;
    for (unsigned int i = 0; i < totalDOFs; i++) {
        x = dofLocation[i][0];
        nodal_dof = i % dim;
        if (nodal_dof == 0) {
            D_trans[i] = 0.01 * x;
        } else {
            D_trans[i] = 0.0;
        }
        V_trans[i] = 0.0;
    }

    // Find A_0 = M^{-1}*(F_0 - K*D_0) (no damping)
    system_matrix.copy_from(M); // system_matrix = M

    K.vmult(RHS, D_trans); // RHS = K*D_trans
    RHS *= -1.0; // RHS = -K*D_trans
    RHS.add(1.0, F); // RHS = F - K*D_trans
    MatrixTools::apply_boundary_values(boundary_values_of_A, system_matrix, A_trans, RHS, false);

    // Solve for solution in system_matrix*A_trans = RHS
    SparseDirectUMFPACK A;
    A.initialize(system_matrix);
    A.vmult(A_trans, RHS); // A_trans = M^{-1}*(F - K*D)

    // Output initial state
    output_trans_results(0);
}
```

```cpp
template <int dim>
void FEM<dim>::solve_trans() {
    // Define delta_t
    const double delta_t = 1e-6;

    const unsigned int totalDOFs = dof_handler.n_dofs(); // Total number of nodes
    Vector<double> D_tilde(totalDOFs), V_tilde(totalDOFs);

    system_matrix.copy_from(M); // No damping
    system_matrix.add(beta * pow(delta_t, 2.0), K);

    // Apply boundary conditions on A_trans before solving the matrix/vector system
    MatrixTools::apply_boundary_values(boundary_values_of_A, system_matrix, A_trans, RHS, false);

    SparseDirectUMFPACK A;
    A.initialize(system_matrix);

    // Loop over time steps. For each time step, update D_transient from D_n to D_{n+1} using the V method
    for (unsigned int t_step = 1; t_step < 1001; t_step++) {
        // Find D_tilde. Remember, D_trans = D_n
        D_tilde = D_trans;
        D_tilde.add(delta_t, V_trans, 0.5 * pow(delta_t, 2.0) * (1.0 - 2.0 * beta), A_trans);

        V_tilde = V_trans;
        V_tilde.add(delta_t * (1.0 - gamma), A_trans);

        K.vmult(RHS, D_tilde);
        RHS *= -1.0;
        RHS.add(1.0, F);

        // Apply boundary conditions
        MatrixTools::apply_boundary_values(boundary_values_of_A, system_matrix, A_trans, RHS, false);

        // Solve for A_trans (A_{n+1}) in system_matrix * A_trans = RHS
        A.vmult(A_trans, RHS);

        // Update D_trans to D_{n+1} using D_tilde and A_trans (A_{n+1})
        D_trans = D_tilde;
        D_trans.add(beta * pow(delta_t, 2.0), A_trans);

        V_trans = V_tilde;
        V_trans.add(gamma * delta_t, A_trans);

        // Output the results at specified intervals
        if (t_step % 50 == 0) {
            std::cout << "Time step: " << t_step << " delta_t: " << delta_t << std::endl;
            output_trans_results(t_step);
        }
    }
}
