```cpp
template <int dim>
void FEM<dim>::define_boundary_conds() {
    const unsigned int totalDOFs = dof_handler.n_dofs(); // Total number of degrees of freedom
    unsigned int nodalDOF;

    // Loop over global degrees of freedom 
    for (unsigned int global_dof = 0; global_dof < totalDOFs; ++global_dof) {
        // Find the nodal dof
        nodalDOF = global_dof % dim; // 0, 1, or 2; corresponds to u1, u2, u3

        // Boundary conditions for problem 1
        if (problem == 1) {
            if (dofLocation[global_dof][2] == 0) {
                boundary_values[global_dof] = 0.0; // Face x3 = 0
            }
        }
        // Boundary conditions for problem 2
        else if (problem == 2) {
            if (dofLocation[global_dof][0] == 0) {
                boundary_values[global_dof] = 0.0; // Fix all displacements on the face x1 = 0
            } 
            else if (dofLocation[global_dof][0] == 1) {
                if (nodalDOF == 1) { // u_2
                    double x2 = dofLocation[global_dof][1];
                    double x3 = dofLocation[global_dof][2];
                    boundary_values[global_dof] = 0.5 + (x2 - 0.5) * std::cos(PI/30.0) - (x3 - 0.5) * std::sin(PI/30.0) - x2;
                }
                if (nodalDOF == 2) { // u_3
                    double x2 = dofLocation[global_dof][1];
                    double x3 = dofLocation[global_dof][2];
                    boundary_values[global_dof] = 0.5 + (x2 - 0.5) * std::sin(PI/30.0) + (x3 - 0.5) * std::cos(PI/30.0) - x3;
                }
            }
        }
    }
}
```

```cpp
template <int dim>
void FEM<dim>::assemble_system() {
    K = 0; F = 0;
    const unsigned int dofs_per_elem = fe.dofs_per_cell;
    const unsigned int num_quad_pts = quadrature_formula.size();
    FullMatrix<double> Klocal(dofs_per_elem, dofs_per_elem);
    Vector<double> Flocal(dofs_per_elem);
    std::vector<unsigned int> local_dof_indices(dofs_per_elem);

    typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(),
        endc = dof_handler.end();
    for (; elem != endc; ++elem) {
        fe_values.reinit(elem);
        elem->get_dof_indices(local_dof_indices);

        Klocal = 0.;
        for (unsigned int q = 0; q < num_quad_pts; ++q) {
            for (unsigned int A = 0; A < nodes_per_elem; ++A) {
                for (unsigned int i = 0; i < dim; ++i) {
                    for (unsigned int B = 0; B < nodes_per_elem; ++B) {
                        for (unsigned int k = 0; k < dim; ++k) {
                            for (unsigned int j = 0; j < dim; ++j) {
                                for (unsigned int l = 0; l < dim; ++l) {
                                    Klocal(dim * A + i, dim * B + k) +=
                                    fe_values.shape_grad(dim * A + i, q)[j] *
                                    C(i, j, k, l) *
                                    fe_values.shape_grad(dim * B + k, q)[l] *
                                    fe_values.JxW(q);
                                }
                            }
                        }
                    }
                }
            }
        }
        Flocal = 0.;
        // Assembly of global K and F
        for (unsigned int i = 0; i < dofs_per_elem; ++i) {
            F(local_dof_indices[i]) += Flocal[i];
            for (unsigned int j = 0; j < dofs_per_elem; ++j) {
                K.add(local_dof_indices[i], local_dof_indices[j], Klocal[i][j]);
            }
        }
    }
    MatrixTools::apply_boundary_values(boundary_values, K, D, F, false);
}
template <int dim>
void FEM<dim>::solve() {
    SparseDirectUMFPACK A;
    A.initialize(K);
    A.vmult(D, F); // D = K^{-1} * F
}
