```cpp
// Specify the Dirichlet boundary conditions
template <int dim>
void FEM<dim>::define_boundary_conds(){
  // Identify dirichlet boundary nodes and specify their values.
  for(unsigned int d = 0; d < nodeLocation.size(); d++){
    if(nodeLocation[d] == 0){
      boundary_values[d] = g1;
    }
    if(nodeLocation[d] == L){
      if(prob == 1 || prob == 3){
        boundary_values[d] = g2;
