Here's how you can implement the setup function which sets up the data structures such as the sparse matrix, global vectors, and defines the quadrature rule:

```cpp
// Setup data structures (sparse matrix, vectors)
template <int dim>
void FEM<dim>::setup_system(){
  // Define constants for the problem
  Area = 1.e-4;
  E = 1.e11;
  f_hat = 1.e12;
  f_bar = 1.e11;
  g1 = 0.;
  g2 = 0.001;
  h = 1.e6;

  // Let deal.II organize degrees of freedom
  dof_handler.distribute_dofs(fe);

  // Get a vector of global degree-of-freedom x-coordinates
  MappingQ1<dim,dim> mapping;
  std::vector< Point<dim, double> > dof_coords(dof_handler.n_dofs());
  nodeLocation.resize(dof_handler.n_dofs());
  DoFTools::map_dofs_to_support_points<dim,dim>(mapping, dof_handler, dof_coords);
  for(unsigned int i = 0; i < dof_coords.size(); i++){
    nodeLocation[i] = dof_coords[i][0];
  }

  // Specify boundary conditions (call the function)
  define_boundary_conds();

  // Define the size of the global matrices and vectors
  sparsity_pattern.reinit(dof_handler.n_dofs(), dof_handler.n_dofs(), dof_handler.max_couplings_between_dofs());
  DoFTools::make_sparsity_pattern(dof_handler, sparsity_pattern);
  sparsity_pattern.compress();
  K.reinit(sparsity_pattern);
  F.reinit(dof_handler.n_dofs());
  D.reinit(dof_handler.n_dofs());

  // Define quadrature rule
  // Include a simpler quad rule
  quadRule = 5; // Number of quadrature points along one dimension
  quad_points.resize(quadRule);
  quad_weight.resize(quadRule);
  if (quadRule == 3){
    quad_points[0] = -sqrt(3./5);
    quad_points[1] = 0.;
    quad_points[2] = sqrt(3./5);
    quad_weight[0] = 5./9;
    quad_weight[1] = 8./9;
    quad_weight[2] = 5./9;
  }
  if (quadRule == 4){
    quad_points[0] = -sqrt((3./7) + (2./7)*sqrt(6./5));
    quad_points[1] = -sqrt((3./7) - (2./7)*sqrt(6./5));
    quad_points[2] = sqrt((3./7) - (2./7)*sqrt(6./5));
    quad_points[3] = sqrt((3./7) + (2./7)*sqrt(6./5));
    quad_weight[0] = (18. - sqrt(30))/36.;
    quad_weight[1] = (18. + sqrt(30))/36.;
    quad_weight[2] = (18. + sqrt(30))/36.;
    quad_weight[3] = (18. - sqrt(30))/36.;
  }
  if (quadRule == 5){
    quad_points[0] = -(1./3.)*sqrt(5. + 2.*sqrt(10./7.));
    quad_points[1] = -(1./3.)*sqrt(5. - 2.*sqrt(10./7.));
    quad_points[2] = 0.0;
    quad_points[3] = (1./3.)*sqrt(5. - 2.*sqrt(10./7.));
    quad_points[4] = (1./3.)*sqrt(5. + 2.*sqrt(10./7.));
    quad_weight[0] = (322. - 13.*sqrt(70.))/900.;
    quad_weight[1] = (322. + 13.*sqrt(70.))/900.;
    quad_weight[2] = 128./225.;
    quad_weight[3] = (322. + 13.*sqrt(70.))/900.;
    quad_weight[4] = (322. - 13.*sqrt(70.))/900.;
  }

  // Just some notes...
  std::cout << "   Number of active elems:       " << triangulation.n_active_cells() << std::endl;
  std::cout << "   Number of degrees of freedom: " << dof_handler.n_dofs() << std::endl;   
}
```

The implementation for assembling the global force vector (F) and stiffness matrix (K) involves iterating over all elements, computing local contributions, and integrating over quadrature points:

```cpp
// Form elemental vectors and matrices and assemble to the global vector (F) and matrix (K)
template <int dim>
void FEM<dim>::assemble_system(){
  K = 0; 
  F = 0;

  const unsigned int dofs_per_elem = fe.dofs_per_cell; // This gives you number of degrees of freedom per element
  FullMatrix<double> Klocal (dofs_per_elem, dofs_per_elem);
  Vector<double> Flocal (dofs_per_elem);
  std::vector<unsigned int> local_dof_indices (dofs_per_elem);
  double h_e, x, f;

  // Loop over elements  
  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(), endc = dof_handler.end();
  for (;elem != endc; ++elem){
    elem->get_dof_indices(local_dof_indices);
    h_e = nodeLocation[local_dof_indices[1]] - nodeLocation[local_dof_indices[0]];

    // Loop over local DOFs and quadrature points to populate Flocal and Klocal.
    Flocal = 0.;
    for(unsigned int A = 0; A < dofs_per_elem; A++){
      for(unsigned int q = 0; q < quadRule; q++){
        x = 0;
        for(unsigned int B = 0; B < dofs_per_elem; B++){
          x += nodeLocation[local_dof_indices[B]] * basis_function(B, quad_points[q]);
        }
        if(prob == 1 || prob == 2){
          f = f_bar * x;
        } else {
          f = f_hat * x * (L - x);
        }
        Flocal[A] += Area * f * h_e / 2. * basis_function(A, quad_points[q]) * quad_weight[q];
      }
    }
    if(prob == 2 || prob == 4){ 
      if(nodeLocation[local_dof_indices[1]] == L){
        Flocal[1] += h;
      }
    }

    Klocal = 0;
    for(unsigned int A = 0; A < dofs_per_elem; A++){
      for(unsigned int B = 0; B < dofs_per_elem; B++){
        for(unsigned int q = 0; q < quadRule; q++){
          Klocal[A][B] += 2. * Area * E / h_e * basis_gradient(A, quad_points[q]) * basis_gradient(B, quad_points[q]) * quad_weight[q];
        }
      }
    }

    for(unsigned int A = 0; A < dofs_per_elem; A++){
      F[local_dof_indices[A]] += Flocal[A];
      for(unsigned int B = 0; B < dofs_per_elem; B++){
        K.add(local_dof_indices[A], local_dof_indices[B], Klocal[A][B]);
      }
    }
  }

  // Apply Dirichlet boundary conditions
  MatrixTools::apply_boundary_values(boundary_values, K, D, F, false);
}
```

The solve function should utilize a direct solver available in the deal.II library to solve the linear system KD=F for the nodal displacement vector D. Here is how you can implement it:

```cpp
// Solve for D in KD=F
template <int dim>
void FEM<dim>::solve(){
  SparseDirectUMFPACK A;
  A.initialize(K);
  A.vmult (D, F); // D = K^{-1} * F
}
```

