      std::cout << problemObject.torque() << std::endl;
    }

    char tag[21];
    if(problem == 1){
      sprintf(tag, "CA3_prob1");
      writeSolutionsToFileCA3_1(problemObject.D, tag);
    }
    else if(problem == 2){
      sprintf(tag, "CA3_prob2");
