The class constructor for this heat conduction problem using the finite element method with deal.II is as follows:
```
template <int dim>
FEM<dim>::FEM (double Alpha, double DeltaT)
	:
  fe (FE_Q<dim>(order), 1),
	dof_handler (triangulation),
	quadrature_formula(quadRule)
	{
	alpha = Alpha;
	delta_t = DeltaT;

	setSavePath();

	nodal_solution_names.push_back("D");
	nodal_data_component_interpretation.push_back(DataComponentInterpretation::component_is_scalar);
}
```

To define and manage the boundary conditions for this transient heat conduction problem, you can set up the conditions using a node location table to determine boundary nodes and apply the specified Dirichlet values. Here's one way to implement this using the deal.II library:
```
template <int dim>
void FEM<dim>::define_boundary_conds(){
	const unsigned int totalNodes = dof_handler.n_dofs(); //Total number of nodes

	const unsigned int dofs_per_elem = fe.dofs_per_cell; //This gives you dofs per element
	std::vector<unsigned int> local_dof_indices (dofs_per_elem);
	unsigned int i;

	//loop over elements  
	typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active (), endc = dof_handler.end();
	for (;elem!=endc; ++elem){
		elem->get_dof_indices (local_dof_indices);
		for (unsigned int d=0; d<dofs_per_elem; ++d){
			i = local_dof_indices[d]; //Global dof number

			if(nodeLocation[i][0] == 0){
				boundary_values_of_D[i] = 300;
				boundary_values_of_V[i] = 0;
			}
			else if(nodeLocation[i][0] == 1){
				boundary_values_of_D[i] = 310;
				boundary_values_of_V[i] = 0;
			}
		}
	}
}
```

To set up the necessary system components like the sparsity pattern, global matrices, and vectors, you can follow the implementation below using deal.II:
```
template <int dim>
void FEM<dim>::setup_system(){
  //Let deal.II organize degrees of freedom
  dof_handler.distribute_dofs (fe);

  //Fill in the Table "nodeLocations" with the x, y, and z coordinates of each node by its global index
  MappingQ1<dim, dim> mapping;
  std::vector< Point<dim,double> > dof_coords(dof_handler.n_dofs());
  nodeLocation.reinit(dof_handler.n_dofs(),dim);
  DoFTools::map_dofs_to_support_points<dim,dim>(mapping,dof_handler,dof_coords);
  for(unsigned int i=0; i<dof_coords.size(); i++){
    for(unsigned int j=0; j<dim; j++){
      nodeLocation[i][j] = dof_coords[i][j];
    }
  }

  //Specify boundary conditions (call the function)
  define_boundary_conds();

  //Define the size of the global matrices and vectors
  sparsity_pattern.reinit (dof_handler.n_dofs(),
                           dof_handler.n_dofs(),
                           dof_handler.max_couplings_between_dofs());
  DoFTools::make_sparsity_pattern (dof_handler, sparsity_pattern);
  sparsity_pattern.compress();
  K.reinit (sparsity_pattern);
  M.reinit (sparsity_pattern);
  system_matrix.reinit (sparsity_pattern);
  D_steady.reinit(dof_handler.n_dofs());
  D_trans.reinit(dof_handler.n_dofs());
  V_trans.reinit(dof_handler.n_dofs());
  RHS.reinit(dof_handler.n_dofs());
  F.reinit(dof_handler.n_dofs());
}
```

To initialize and assemble the mass and stiffness matrices with the given material properties using deal.II, you can use the following code snippet for the `assemble_system` function:
```
template <int dim>
void FEM<dim>::assemble_system(){
  M=0; K=0; F=0;

  FEValues<dim> fe_values(fe,
                          quadrature_formula,
                          update_values | 
                          update_gradients | 
                          update_JxW_values);

  const unsigned int                  dofs_per_elem = fe.dofs_per_cell;
  unsigned int                        num_quad_pts = quadrature_formula.size();
  FullMatrix<double>                  Mlocal (dofs_per_elem, dofs_per_elem);
  FullMatrix<double>                  Klocal (dofs_per_elem, dofs_per_elem);
  Vector<double>                      Flocal (dofs_per_elem);
  std::vector<unsigned int> local_dof_indices (dofs_per_elem);
  double                                      rho = 3.8151e6;

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active (),
                                                 endc = dof_handler.end();
  for (;elem!=endc; ++elem){
    elem->get_dof_indices (local_dof_indices);
    fe_values.reinit(elem);

    Mlocal = 0.;
    for(unsigned int q=0; q<num_quad_pts; q++){
      for(unsigned int A=0; A<fe.dofs_per_cell; A++){
        for(unsigned int B=0; B<fe.dofs_per_cell; B++){
          Mlocal(A,B) += fe_values.shape_value(A,q)*rho*fe_values.shape_value(B,q)*fe_values.JxW(q);
        }
      }
    }

    FullMatrix<double> kappa(dim,dim);
    kappa[0][0] = 385.;
    kappa[1][1] = 385.;
    kappa[2][2] = 385.;

    Klocal = 0.;
    for(unsigned int A=0; A<fe.dofs_per_cell; A++){
      for(unsigned int B=0; B<fe.dofs_per_cell; B++){
        for(unsigned int q=0; q<num_quad_pts; q++){
          for(unsigned int i=0; i<dim; i++){
            for(unsigned int j=0; j<dim; j++){
              Klocal(A,B) += fe_values.shape_grad(A,q)[i]*kappa[i][j]*fe_values.shape_grad(B,q)[j]*fe_values.JxW(q);
            }
          }
        }
      }
    }

    for (unsigned int i=0; i<dofs_per_elem; ++i){
      for (unsigned int j=0; j<dofs_per_elem; ++j){
        K.add(local_dof_indices[i], local_dof_indices[j], Klocal[i][j]);
        M.add(local_dof_indices[i], local_dof_indices[j], Mlocal[i][j]);
      }
    }
  }
}
```

The `apply_initial_conditions` function to implement this temperature distribution using the deal.II library is written as follows:
```
template <int dim>
void FEM<dim>::apply_initial_conditions(){
  const unsigned int totalNodes = dof_handler.n_dofs(); //Total number of nodes

  for(unsigned int i=0; i<totalNodes; i++){
    double x1 = nodeLocation[i][0];
    if(x1 < 0.5){
      D_trans[i] = 300; // Initial condition
    }
    else if(x1 >= 0.5){
      D_trans[i] = 300 + 20*(x1 - 0.5); // Initial condition
    }
  }

  system_matrix.copy_from(M); //system_matrix = M

  K.vmult(RHS,D_trans); //RHS = K*D_trans
  RHS *= -1.;           //RHS = -1.*RHS = -K*D_trans
  RHS.add(1.,F);        //RHS = RHS + 1.*F = F - K*D_trans

  MatrixTools::apply_boundary_values(boundary_values_of_V, system_matrix, V_trans, RHS, false);

  SparseDirectUMFPACK  A;
  A.initialize(system_matrix);
  A.vmult (V_trans, RHS); //V_trans=system_matrix^{-1}*RHS

  output_trans_results(0);

  double current_l2norm = l2norm();
  std::vector<double> saveL2 = {0.0,current_l2norm};
  l2norm_results.push_back(saveL2);
}
```

Here's how you can advance the solution in time for a transient heat conduction problem using time-stepping methods with parameter \(\alpha\) in the `solve_trans` function:
```
template <int dim>
void FEM<dim>::solve_trans(){
  apply_initial_conditions();

  std::cout << "Time step: " << delta_t << std::endl;
  std::cout << "Alpha: " << alpha << std::endl;

  const int phys_t = 3000;  // Run for 3000s of physical time
  const int output_t = 100; // Output every 100s of physical time

  const unsigned int num_steps = int(phys_t/delta_t);
  const int mod_t = int(output_t/delta_t);

  const unsigned int totalNodes = dof_handler.n_dofs(); //Total number of nodes
  Vector<double> D_tilde(totalNodes);

  for(unsigned int t_step=1; t_step<num_steps+1; t_step++){
    D_tilde = D_trans;
    D_tilde.add(delta_t*(1. - alpha), V_trans);

    system_matrix.copy_from(M);
    system_matrix.add(alpha*delta_t, K);

    K.vmult(RHS, D_tilde);
    RHS *= -1.;
    RHS.add(1., F);

    MatrixTools::apply_boundary_values(boundary_values_of_V, system_matrix, V_trans, RHS, false);

    SparseDirectUMFPACK A;
    A.initialize(system_matrix);
    A.vmult (V_trans, RHS);

    D_trans = D_tilde;
    D_trans.add(alpha*delta_t, V_trans);

    if(t_step % mod_t == 0){
      output_trans_results(t_step*delta_t);

      double current_l2norm = l2norm();
      std::vector<double> saveL2 = {t_step*delta_t, current_l2norm};
      l2norm_results.push_back(saveL2);
    }
  }
}
```

