Here is how the `define_boundary_conds` function is implemented:

```cpp
template <int dim>
void FEM<dim>::define_boundary_conds(){
  f = -10000.0;
  kbar = 385.0;
  const unsigned int totalNodes = dof_handler.n_dofs(); //Total number of nodes

  if(prob == 1){
    for(unsigned int globalNode=0; globalNode<totalNodes; globalNode++){
      if(nodeLocation[globalNode][1] == 0.0){
        boundary_values[globalNode] = 300.0*(1.0+(1.0/3.0)*nodeLocation[globalNode][0]);
      }
      if(nodeLocation[globalNode][1] == 0.08){
        boundary_values[globalNode] = 310.0*(1.0+8.0*pow(nodeLocation[globalNode][0],2.0));
      }
    }
  } else if(prob == 2){
    for(unsigned int globalNode=0; globalNode<totalNodes; globalNode++){
      if(nodeLocation[globalNode][1] == 0.0){
        boundary_values[globalNode] = 100.0+(f/(4*kbar))*(pow(nodeLocation[globalNode][0],2.0));
      }
      if(nodeLocation[globalNode][1] == 0.08){
        boundary_values[globalNode] = 100.0+(f/(4*kbar))*(pow(nodeLocation[globalNode][0],2.0)+0.0064);
      }
      if(nodeLocation[globalNode][0] == 0.0){
        boundary_values[globalNode] = 100.0+(f/(4*kbar))*(pow(nodeLocation[globalNode][1],2.0));
      }
      if(nodeLocation[globalNode][0] == 0.03){
        boundary_values[globalNode] = 100.0+(f/(4*kbar))*(pow(nodeLocation[globalNode][1],2.0)+0.0009);
      }
    }
  }
}
