The `basis_gradient` function is implemented as:

```cpp
template <int dim>
std::vector<double> FEM<dim>::basis_gradient(unsigned int node, double xi_1, double xi_2){
  std::vector<double> values(dim);

  values[0] = (xi_2 + xi_A[node][1])/(4.*xi_A[node][0]*xi_A[node][1]);
  values[1] = (xi_1 + xi_A[node][0])/(4.*xi_A[node][0]*xi_A[node][1]);

  return values;
}
