The basis_function method can be implemented as follows:

```cpp
template <int dim>
double FEM<dim>::basis_function(unsigned int node, double xi_1, double xi_2, double xi_3){

	double value = 0.; //Store the value of the basis function in this variable

	if(node == 0){
		value = (1. - xi_1)*(1 - xi_2)*(1 - xi_3)/8.;
	}
	else if(node == 1){
		value = (1. + xi_1)*(1 - xi_2)*(1 - xi_3)/8.;
	}
	else if(node == 2){
		value = (1. - xi_1)*(1 + xi_2)*(1 - xi_3)/8.;
	}
	else if(node == 3){
		value = (1. + xi_1)*(1 + xi_2)*(1 - xi_3)/8.;
	}
	else if(node == 4){
		value = (1. - xi_1)*(1 - xi_2)*(1 + xi_3)/8.;
	}
	else if(node == 5){
		value = (1. + xi_1)*(1 - xi_2)*(1 + xi_3)/8.;
	}
	else if(node == 6){
		value = (1. - xi_1)*(1 + xi_2)*(1 + xi_3)/8.;
	}
	else if(node == 7){
		value = (1. + xi_1)*(1 + xi_2)*(1 + xi_3)/8.;
	}
	else{
		std::cout << "Error: invalid node number.\n";
		exit(1);
	}

	return value;
}
```

The basis_gradient function can be implemented as follows:

```cpp
template <int dim>
std::vector<double> FEM<dim>::basis_gradient(unsigned int node, double xi_1, double xi_2, double xi_3){
	/*You need to calculate the value of the derivative of the specified basis function and order at the given quadrature pt.
	Note that this is the derivative with respect to xi (not x)*/

	std::vector<double> values(dim,0.0); //Store the value of the gradient of the basis function in this variable

	if(node == 0){
		values[0] = -(1 - xi_2)*(1 - xi_3)/8.;
		values[1] = -(1. - xi_1)*(1 - xi_3)/8.;
		values[2] = -(1. - xi_1)*(1 - xi_2)/8.;
	}
	else if(node == 1){
		values[0] = (1 - xi_2)*(1 - xi_3)/8.;
		values[1] = -(1. + xi_1)*(1 - xi_3)/8.;
		values[2] = -(1. + xi_1)*(1 - xi_2)/8.;
	}
	else if(node == 2){
		values[0] = -(1 + xi_2)*(1 - xi_3)/8.;
		values[1] = (1. - xi_1)*(1 - xi_3)/8.;
		values[2] = -(1. - xi_1)*(1 + xi_2)/8.;
	}
	else if(node == 3){
		values[0] = (1 + xi_2)*(1 - xi_3)/8.;
		values[1] = (1. + xi_1)*(1 - xi_3)/8.;
		values[2] = -(1. + xi_1)*(1 + xi_2)/8.;
	}
	else if(node == 4){
		values[0] = -(1 - xi_2)*(1 + xi_3)/8.;
		values[1] = -(1. - xi_1)*(1 + xi_3)/8.;
		values[2] = (1. - xi_1)*(1 - xi_2)/8.;
	}
	else if(node == 5){
		values[0] = (1 - xi_2)*(1 + xi_3)/8.;
		values[1] = -(1. + xi_1)*(1 + xi_3)/8.;
		values[2] = (1. + xi_1)*(1 - xi_2)/8.;
	}
	else if(node == 6){
		values[0] = -(1 + xi_2)*(1 + xi_3)/8.;
		values[1] = (1. - xi_1)*(1 + xi_3)/8.;
		values[2] = (1. - xi_1)*(1 + xi_2)/8.;
	}
	else if(node == 7){
		values[0] = (1 + xi_2)*(1 + xi_3)/8.;
		values[1] = (1. + xi_1)*(1 + xi_3)/8.;
		values[2] = (1. + xi_1)*(1 + xi_2)/8.;
	}
	else{
		std::cout << "Error: invalid node number.\n";
		exit(1);
	}

	return values;
}
```

