The define_boundary_conds method can be implemented as follows:

```cpp
template <int dim>
void FEM<dim>::define_boundary_conds(){

	//Identify dirichlet boundary nodes and specify their values.
	for(unsigned int i=0; i<dof_handler.n_dofs(); i++){
		if(nodeLocation[i][0] == 0.){
			boundary_values[i] = 300.*(1 + 1./3.*(nodeLocation[i][1] + nodeLocation[i][2]));
		}
		else if(nodeLocation[i][0] == 0.04){
			boundary_values[i] = 310.*(1 + 1./3.*(nodeLocation[i][1] + nodeLocation[i][2]));
		}
	}
}
