Here is the implementation of the `torque` function for calculating the torque about the x1-axis:
```cpp
template <int dim>
double FEM<dim>::torque(){

  //For surface integration/quadrature points
  FEFaceValues<dim> fe_face_values (fe,
                    face_quadrature_formula, 
                    update_values |  
                    update_gradients | 
                    update_quadrature_points | 
                    update_JxW_values);

  double torque = 0.;

  unsigned int faces_per_elem = GeometryInfo<dim>::faces_per_cell;
  const unsigned int            nodes_per_elem = GeometryInfo<dim>::vertices_per_cell;
  const unsigned int dofs_per_elem = fe.dofs_per_cell; //This gives you dofs per element
  unsigned int num_face_quad_pts = face_quadrature_formula.size(); //Total number of quad points on a face
  std::vector<unsigned int> local_dof_indices (dofs_per_elem); //Relates local dof numbering to global dof numbering
  double y, z, sigma_12, sigma_13;
  FullMatrix<double> du_dx(dim,dim);
  unsigned int elemDOF;

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active (), endc = dof_handler.end();
  for (;elem!=endc; ++elem){

    elem->get_dof_indices (local_dof_indices);

    for (unsigned int f=0; f < faces_per_elem; f++){
      if(elem->face(f)->center()[0] == 1){
        fe_face_values.reinit (elem, f); //Retrieve values from current element and face

        for (unsigned int q=0; q<num_face_quad_pts; ++q){
          y = fe_face_values.quadrature_point(q)[1];
          z = fe_face_values.quadrature_point(q)[2];
          sigma_12 = 0.; sigma_13 = 0.; du_dx = 0;

          for (unsigned int A=0; A<nodes_per_elem; A++){ // Loop over all element nodes
            for(unsigned int k=0; k<dim; k++){ // Loop over nodal dofs
              elemDOF = dim*A+k;
              for(unsigned int l=0;l<dim;l++){
                du_dx[k][l] += D[local_dof_indices[elemDOF]]*fe_face_values.shape_grad(elemDOF,q)[l];
              }
            }
          }

          for(unsigned int k=0; k<dim; k++){
            for(unsigned int l=0; l<dim; l++){
              sigma_12 += C(0,1,k,l)*du_dx[k][l];
              sigma_13 += C(0,2,k,l)*du_dx[k][l];
            }
          }

          torque += (sigma_13*y - sigma_12*z)*fe_face_values.JxW(q);
        }
      }
    }
  }
  return torque;
}
```

Here is how the `define_boundary_conds` function is implemented:
```cpp
template <int dim>
void FEM<dim>::define_boundary_conds(){

  double x1, x2, x3;
  unsigned int nodal_dof;

  // Loop over global degrees of freedom 
  for(unsigned int global_dof=0; global_dof<dof_handler.n_dofs(); global_dof++){
    nodal_dof = global_dof%dim;
    x1 = dofLocation[global_dof][0];
    x2 = dofLocation[global_dof][1];
    x3 = dofLocation[global_dof][2];

    if(problem == 1){
      if(x3 == 0){
        boundary_values[global_dof] = 0;
      }
    }
    else if(problem == 2){
      if(x1 == 0){
        boundary_values[global_dof] = 0;
      }
      else if(x1 == 1){
        //Check if global_dof corresponds to u_2)
        if(nodal_dof == 1){
          boundary_values[global_dof] = 0.5 + (x2 - 0.5)*std::cos(PI/30.) - (x3 - 0.5)*std::sin(PI/30.) - x2;
        }
        //Check if global_dof corresponds to u_3)
        else if(nodal_dof == 2){
          boundary_values[global_dof] = 0.5 + (x2 - 0.5)*std::sin(PI/30.) + (x3 - 0.5)*std::cos(PI/30.) - x3;
        }
      }
    }
  }
}
```

Here is the implementation of the `assemble_system` function:
```cpp
template <int dim>
void FEM<dim>::assemble_system(){

  FEValues<dim> fe_values (fe,
             quadrature_formula, 
             update_values | 
             update_gradients | 
             update_JxW_values);

  FEFaceValues<dim> fe_face_values (fe,
                  face_quadrature_formula, 
                  update_values | 
                  update_quadrature_points | 
                  update_JxW_values);

  K=0; F=0;
  const unsigned int       nodes_per_elem = GeometryInfo<dim>::vertices_per_cell;

  const unsigned int       dofs_per_elem = fe.dofs_per_cell;
  const unsigned int       num_quad_pts = quadrature_formula.size();
  const unsigned int       num_face_quad_pts = face_quadrature_formula.size();
  const unsigned int       faces_per_elem = GeometryInfo<dim>::faces_per_cell;
  FullMatrix<double>       Klocal (dofs_per_elem, dofs_per_elem);
  Vector<double>        Flocal (dofs_per_elem);
  std::vector<unsigned int> local_dof_indices (dofs_per_elem);

  typename DoFHandler<dim>::active_cell_iterator elem = dof_handler.begin_active(),
    endc = dof_handler.end();
  for (;elem!=endc; ++elem){
    fe_values.reinit(elem);

    elem->get_dof_indices (local_dof_indices);
    Klocal = 0.;

    for (unsigned int q=0; q<num_quad_pts; ++q){
      for (unsigned int A=0; A<nodes_per_elem; A++) {
        for(unsigned int i=0; i<dim; i++){
          for (unsigned int B=0; B<nodes_per_elem; B++) {
            for(unsigned int k=0; k<dim; k++){
              for (unsigned int j = 0; j<dim; j++){
                for (unsigned int l = 0; l<dim; l++){
                  Klocal(dim*A+i,dim*B+k) +=  fe_values.shape_grad(dim*A+i, q)[j]*C(i,j,k,l)*fe_values.shape_grad(dim*B+k, q)[l]*fe_values.JxW(q);
                }
              }
            }
          }
        }
      }
    }

    Flocal = 0.;

    Vector<double> h(dim); h=0.;
    for (unsigned int f=0; f < faces_per_elem; f++){
      fe_face_values.reinit (elem, f);
      if(elem->face(f)->center()[2] == 1){
        for (unsigned int q=0; q<num_face_quad_pts; ++q){
          if(problem == 1){
            h(2) = 1.e9*fe_face_values.quadrature_point(q)[0];
          }

          for (unsigned int A=0; A<nodes_per_elem; A++){
            for(unsigned int i=0; i<dim; i++){
              Flocal(dim*A+i) += h(i)*fe_face_values.shape_value(dim*A+i,q)*fe_face_values.JxW(q);
            }
          }
        }
      }
    }

    for (unsigned int i=0; i<dofs_per_elem; ++i){
      F(local_dof_indices[i]) += Flocal[i];
      for (unsigned int j=0; j<dofs_per_elem; ++j){
        K.add (local_dof_indices[i], local_dof_indices[j], Klocal[i][j]);
      }
    }
  }

  MatrixTools::apply_boundary_values (boundary_values, K, D, F, false);
}
```

