int main (){
  try{
    deallog.depth_console (0);

    const int dimension = 3;

    unsigned int problem = 1; //1 or 2

    std::vector<unsigned int> num_of_elems(dimension);
    num_of_elems[0] = 5;
    num_of_elems[1] = 5;
